/* Helper functional interface and method to emulate JUnit‑5's assertDoesNotThrow in a JUnit‑4 test suite */
@FunctionalInterface
private interface ThrowingRunnable {
    void run() throws Exception;
}

private static void assertDoesNotThrow(ThrowingRunnable runnable, String message) {
    try {
        runnable.run();
    } catch (Exception e) {
        fail(message + ": " + e);
    }
}

